<script lang="ts">
  import { onMount } from 'svelte';
  import * as THREE from 'three';
  import Viewport from './Viewport.svelte';
  import ProfileManager from './ProfileManager.svelte';
  import Documentation from './Documentation.svelte';
  import ReadinessPanel from './ReadinessPanel.svelte';
  import SupportSettings from './SupportSettings.svelte';
  import SupportComparison from './SupportComparison.svelte';
  import { api, json, modes, duration, number } from './api';
  import type { AppState, Model, Transform, Vec3, Job, Preview, Printer, MaterialCompatibility,SupportMode,SupportStyle,SupportPlacement,Preferences,Readiness } from './api';
  let state: AppState | null = null;
  let printerId = '', filamentId = '', mode = 'balanced';
  let model: Model | null = null;
  let vertices: number[] = [];
  let transform: Transform = {rotation: [0, 0, 0], scale: [1, 1, 1], position: [0, 0, 0]};
  let job: Job | null = null;
  let preview: Preview | null = null;
  let tab: 'prepare'|'preview' = 'prepare';
  let layer = 0, printOrder = 100;
  let travel = false, singleLayer = false, dragActive = false;
  let initialLoading = true, importing = false, submitting = false, profileOpen = false, engineOpen = false, reportOpen = false;
  let error = '', notice = '', enginePath = '', engineSaving = false;
  let activeTool: 'move'|'rotate'|'scale' = 'move';
  let uniformScale = true;
  let budget = 64, minWalls = 2, minInfill = 10, supports = true;
  let supportMode:SupportMode='auto',supportStyle:SupportStyle='auto',supportPlacement:SupportPlacement='everywhere',supportAngle=45;
  let readiness:Readiness|null=null,showRisks=true;
  let currentPreferences:Preferences;
  let useLoadDirection = false, loadDirection: Vec3 = [0, 0, 1];
  let light = false;
  let fileInput: HTMLInputElement;
  let printerInput: HTMLInputElement;
  let printerImportBusy = false, printerErrors: string[] = [], printerDraftText = '';
  let preferencesLoaded = false;
  let profileKind: 'printer'|'filament'|'optimization' = 'printer';
  let profileInitialText = '', profileInitialErrors: string[] = [];
  let guideOpen = false, guidePath = 'configuration/getting-started.md';
  let materials: MaterialCompatibility[] = [], materialsLoading = false, materialsError = '', materialsPrinterId = '';
  let placementWorker: Worker | null = null, placementBusy = false, placementKey = '', placementFits = true, placementReasons: string[] = [], exactDimensions: number[] = [];
  let viewport: {fit: () => void; view: (direction: 'top'|'front'|'iso') => void; orient: () => void};
  let timer: ReturnType<typeof setTimeout> | undefined;
  let alive = true;
  let dragDepth = 0;
  $: printer = state?.printers.find(p => p.id === printerId);
  $: filament = state?.filaments.find(f => f.id === filamentId);
  $: materialStatus = materials.find(m => m.profile.id === filamentId);
  $: materialCompatible = !!printer && !materialsLoading && !!materialStatus?.compatible;
  $: supports=supportMode!=='off';
  $: currentPreferences={schemaVersion:'1.0',mode,budget:Number(budget),minWalls:Number(minWalls),minInfill:Number(minInfill)/100,supports,supportMode,supportStyle,supportPlacement,supportAngle:Number(supportAngle),...(useLoadDirection?{loadDirection}:{})};
  $: if (printer && printer.id !== materialsPrinterId) void loadMaterials(printer.id);
  $: nextPlacementKey = printer && model ? JSON.stringify({id:model.id,printer:printer.id,buildVolume:printer.buildVolume,transform}) : '';
  $: if (nextPlacementKey !== placementKey) updatePlacement(nextPlacementKey, printer);
  $: busy = !!job && !['complete', 'failed', 'cancelled'].includes(job.status);
  $: selectedMode = modes.find(m => m.id === mode)!;
  $: dimensions = model ? transformedDimensions(model, transform) : [0, 0, 0];
  $: currentLayerZ = preview?.layers[layer] ?? 0;
  $: report = job?.report;
  $: progress = Math.max(0, Math.min(100, (job?.progress ?? 0) <= 1 ? (job?.progress ?? 0) * 100 : job?.progress ?? 0));
  $: if (typeof document !== 'undefined') document.documentElement.dataset.theme = light ? 'light' : 'dark';
  function transformedDimensions(m: Model, t: Transform): Vec3 {
    const size = m.bounds.max.map((v, i) => v - m.bounds.min[i]);
    const matrix = new THREE.Matrix4().compose(new THREE.Vector3(), new THREE.Quaternion().setFromEuler(new THREE.Euler(t.rotation[0] * Math.PI / 180, t.rotation[1] * Math.PI / 180, t.rotation[2] * Math.PI / 180, 'ZYX')), new THREE.Vector3(...t.scale));
    const box = new THREE.Box3();
    for (let i = 0; i < 8; i++) box.expandByPoint(new THREE.Vector3((i & 1 ? .5 : -.5) * size[0], (i & 2 ? .5 : -.5) * size[1], (i & 4 ? .5 : -.5) * size[2]).applyMatrix4(matrix));
    const d = box.getSize(new THREE.Vector3()); return [d.x, d.y, d.z];
  }
  function getCenter(p: Printer | undefined): Vec3 {return !p || p.buildVolume.origin === 'center' ? [0, 0, 0] : [p.buildVolume.width / 2, p.buildVolume.depth / 2, 0];}
  function openProfiles(kind: typeof profileKind = 'printer', text = '', errors: string[] = []) {profileKind = kind; profileInitialText = text; profileInitialErrors = errors; profileOpen = true;}
  function openGuide(path = 'configuration/getting-started.md') {guidePath = path; guideOpen = true;}
  function applySupportPreferences(p:Partial<Preferences>) {supportMode=p.supportMode??(p.supports===false?'off':'auto');supportStyle=p.supportStyle??'auto';supportPlacement=p.supportPlacement??'everywhere';supportAngle=p.supportAngle||45;}
  async function savePreferences() {try{await api('/api/profiles',json({kind:'optimization',profile:currentPreferences}));notice='Current objectives, constraints, and support preferences saved locally.';}catch(e){error=message(e);}}
  function readinessAction(action:string) {if(action==='supports'){invalidate();supportMode='auto';notice='Auto supports selected. The geometry recommendation will determine whether supports are generated.';}else if(action==='orient'){viewport.orient();}else if(action==='place_on_bed'){invalidate();transform={...transform,position:[transform.position[0],transform.position[1],0]};notice='Placed the model on the build plate. Bed contact will be recalculated.';}else if(action==='scale'){activeTool='scale';tab='prepare';notice='Review the scale controls and machine dimensions before changing functional geometry.';}else if(action==='brim'){openGuide('configuration/supports.md');notice='A brim is a bed-adhesion suggestion. This release does not apply a brim; review orientation and bed contact.';}else{tab='prepare';viewport.view('iso');notice='Inspect the highlighted sampled risk faces, contact area, and unsupported features.';}}
  async function loadMaterials(id: string) {materialsPrinterId = id; materialsLoading = true; materialsError = ''; materials = []; try {const result = await api<MaterialCompatibility[]>(`/api/materials?printerId=${encodeURIComponent(id)}`); if (id !== materialsPrinterId) return; materials = result; if (!result.some(m => m.profile.id === filamentId && m.compatible)) filamentId = result.find(m => m.compatible)?.profile.id ?? '';} catch (e) {if (id === materialsPrinterId) materialsError = message(e);} finally {if (id === materialsPrinterId) materialsLoading = false;}}
  async function selectPrinter() {invalidate(); try {await api('/api/printers/select', json({id: printerId})); const selected = state?.printers.find(p => p.id === printerId); transform = {...transform,position:getCenter(selected)};} catch(e) {error = message(e); await refresh();}}
  function updatePlacement(key: string, p: Printer | undefined) {placementKey = key; placementWorker?.terminate(); placementWorker = null; placementBusy = false; placementFits = true; placementReasons = []; exactDimensions = []; if (!key || !p || !vertices.length) return; placementBusy = true; placementWorker = new Worker(new URL('./placement.worker.ts', import.meta.url), {type:'module'}); placementWorker.onmessage = event => {if (key !== placementKey) return; placementFits = event.data.fits; placementReasons = event.data.reasons; exactDimensions = event.data.dimensions; placementBusy = false; placementWorker?.terminate(); placementWorker = null;}; placementWorker.onerror = () => {placementBusy = false; placementFits = false; placementReasons = ['Placement analysis failed. Reimport the model before slicing.'];placementWorker?.terminate();placementWorker=null;}; placementWorker.postMessage({vertices,transform,printer:p});}
  async function importPrinter(file: File | undefined) {if(!file || printerImportBusy || busy) return; printerImportBusy=true; printerErrors=[]; error=''; notice=''; try {if(file.size>2*1024*1024) throw new Error('Printer profiles must be smaller than 2 MiB.'); if(!/\.json$/i.test(file.name)) throw new Error('Choose a portable printer profile ending in .json.'); const profile=JSON.parse(await file.text()); printerDraftText=JSON.stringify(profile,null,2); const validation=await api<{valid:boolean;errors:string[]}>('/api/profiles/validate',json({kind:'printer',profile})); if(!validation.valid){printerErrors=validation.errors??['This profile failed validation.']; if(printer) openProfiles('printer',printerDraftText,printerErrors); return;} await api('/api/profiles',json({kind:'printer',profile})); await profileSaved('printer',profile); printerDraftText=''; notice=`${profile.name} is now your active printer. Its declared limits define this workspace.`;} catch(e){printerErrors=[message(e)];if(printer)error=message(e);} finally{printerImportBusy=false;if(printerInput) printerInput.value='';}}
  function invalidate() {if (timer) clearTimeout(timer); job = null; preview = null; tab = 'prepare'; reportOpen = false; error = '';}
  function changeTransform(field: keyof Transform, axis: number, event: Event) {
    const value = Number((event.target as HTMLInputElement).value); if (!Number.isFinite(value) || (field === 'scale' && value <= 0)) return;
    invalidate(); const values = [...transform[field]] as Vec3; values[axis] = field === 'scale' ? value / 100 : value;
    if (field === 'scale' && uniformScale) transform = {...transform, scale: [value / 100, value / 100, value / 100]}; else transform = {...transform, [field]: values};
  }
  function center() {invalidate(); transform = {...transform, position: getCenter(printer)};}
  function resetTransform() {invalidate(); transform = {rotation: [0, 0, 0], scale: [1, 1, 1], position: getCenter(printer)};}
  async function refresh() {
    try {const result = await api<AppState>('/api/state'); state = result; if(!preferencesLoaded && result.preferences){const p=result.preferences;mode=p.mode;budget=p.budget;minWalls=p.minWalls;minInfill=p.minInfill*100;applySupportPreferences(p);if(p.loadDirection){loadDirection=p.loadDirection;useLoadDirection=p.loadDirection.some(v=>v!==0);}preferencesLoaded=true;} printerId = result.activePrinterId ?? (result.printers.some(p => p.id === printerId) ? printerId : result.printers[0]?.id ?? ''); if (!result.filaments.some(f => f.id === filamentId)) filamentId = ''; enginePath = result.engine.path ?? ''; if (result.warnings?.length) notice = result.warnings.join(' · '); if (!model) transform = {...transform, position: getCenter(result.printers.find(p => p.id === printerId))}; error = ''; if (printerId) void loadMaterials(printerId);}
    catch (e) {error = message(e);} finally {initialLoading = false;}
  }
  async function profileSaved(kind: 'printer'|'filament'|'optimization', profile: Record<string, unknown>) {
    await refresh(); invalidate();
    if (kind === 'printer') {printerId = String(profile.id); transform = {...transform, position: getCenter(state?.printers.find(p => p.id === printerId))}; await loadMaterials(printerId);}
    else if (kind === 'filament') {if(printerId) await loadMaterials(printerId); filamentId = String(profile.id);}
    else {mode = String(profile.mode); budget = Number(profile.budget); minWalls = Number(profile.minWalls); minInfill = Number(profile.minInfill) * 100; applySupportPreferences(profile as unknown as Partial<Preferences>); if (Array.isArray(profile.loadDirection) && profile.loadDirection.length === 3) {loadDirection = profile.loadDirection.map(Number) as Vec3; useLoadDirection = loadDirection.some(v => v !== 0);} else useLoadDirection = false;} profileOpen=false; printerErrors=[];
  }
  async function importModel(file: File | undefined) {
    if (!file || importing || busy) return;
    if (!printer) {error='Import and validate your printer profile before adding a model.';return;}
    error = ''; notice = '';
    try {
      if (!/\.(stl|3mf)$/i.test(file.name)) throw new Error('Choose an STL or 3MF model.');
      if (file.size > 64 * 1024 * 1024) throw new Error('This release accepts model files up to 64 MiB and 500,000 triangles.');
      importing = true; invalidate(); const form = new FormData(); form.append('file', file);
      const imported = await api<Model>('/api/models', {method: 'POST', body: form});
      const mesh = await api<{vertices: number[]}>(`/api/models/${encodeURIComponent(imported.id)}/mesh`);
      model = imported; vertices = mesh.vertices; transform = {rotation: [0, 0, 0], scale: [1, 1, 1], position: getCenter(printer)};
      notice = 'Model imported. Review the printer profile and place it on the plate.';
    } catch (e) {error = message(e);} finally {importing = false; if (fileInput) fileInput.value = '';}
  }
  async function slice() {
    if (!model || !printer || !filament || !materialCompatible || !placementFits || placementBusy || busy || submitting) return;
    error = ''; notice = ''; submitting = true; preview = null; tab = 'prepare';
    try {
      job = await api<Job>('/api/jobs', json({modelId: model.id, printer, filament, mode, transform, budget: Number(budget), supports,supportMode,supportStyle,supportPlacement,supportAngle:Number(supportAngle), minWalls: Number(minWalls), minInfill: Number(minInfill) / 100, ...(useLoadDirection ? {loadDirection} : {})}));
      schedulePoll(job.id);
    } catch (e) {error = message(e);} finally {submitting = false;}
  }
  function schedulePoll(id: string) {if (timer) clearTimeout(timer); timer = setTimeout(() => poll(id), 450);}
  async function poll(id: string) {
    try {
      const result = await api<Job>(`/api/jobs/${encodeURIComponent(id)}`); if (!alive || job?.id !== id) return; job = result;
      if (result.status === 'complete') {preview = await api<Preview>(`/api/jobs/${encodeURIComponent(id)}/preview`); if (!alive || job?.id !== id) return; layer = Math.max(0, preview.layers.length - 1); printOrder = 100; tab = 'preview'; notice = 'Slicing complete. Inspect toolpaths layer by layer before exporting.';}
      else if (result.status === 'failed') error = result.error || result.message || 'Slicing failed.';
      else if (result.status !== 'cancelled') schedulePoll(id);
    } catch (e) {error = message(e); if (alive && job?.id === id) schedulePoll(id);}
  }
  async function cancel() {if (!job) return; try {await api(`/api/jobs/${encodeURIComponent(job.id)}`, {method: 'DELETE'}); schedulePoll(job.id);} catch (e) {error = message(e);}}
  async function saveEngine() {engineSaving = true; error = ''; try {const engine = await api<AppState['engine']>('/api/engine', json({path: enginePath})); if (state) state = {...state, engine}; engineOpen = false; notice = 'Native slicing engine connected.';} catch (e) {error = message(e);} finally {engineSaving = false;}}
  function message(e: unknown) {return e instanceof Error ? e.message : String(e);}
  function changeLabel(value: number | undefined) {return value === undefined || !Number.isFinite(value) ? 'unavailable' : Math.abs(value) < .05 ? 'unchanged' : `${number(Math.abs(value))}% ${value > 0 ? 'less' : 'more'}`;}
  function drop(event: DragEvent) {event.preventDefault(); dragActive = false; dragDepth = 0; const file=event.dataTransfer?.files[0]; if(file && /\.json$/i.test(file.name)) void importPrinter(file); else void importModel(file);}
  async function downloadGcode() {
    if (!job || job.status !== 'complete') return;
    if (state?.nativeDialogs) {try {const result = await api<{saved?: boolean; path?: string; cancelled?: boolean}>(`/api/jobs/${encodeURIComponent(job.id)}/save`, json({})); if (result.saved) notice = `G-code saved to ${result.path}`;} catch (e) {error = message(e);} return;}
    const a = document.createElement('a'); a.href = `/api/jobs/${encodeURIComponent(job.id)}/gcode`; a.download = (model?.name.replace(/\.(stl|3mf)$/i, '') ?? 'print') + '.gcode'; a.click();
  }
  onMount(() => {alive = true; try {light = localStorage.getItem('forge-theme') === 'light';} catch {} void refresh(); return () => {alive = false; if (timer) clearTimeout(timer);placementWorker?.terminate();};});
  function toggleTheme() {light = !light; try {localStorage.setItem('forge-theme', light ? 'light' : 'dark');} catch {}}
</script>

<svelte:window on:keydown={(e) => {if (e.key === 'Escape') {if(guideOpen) guideOpen=false;else {profileOpen = false; engineOpen = false; reportOpen = false;}}}} on:dragenter={(e) => {if (e.dataTransfer?.types.includes('Files')) {e.preventDefault(); dragDepth++; dragActive = true;}}} on:dragleave={() => {dragDepth--; if (dragDepth <= 0) dragActive = false;}} on:dragover={(e) => e.preventDefault()} on:drop={drop}/>

<div class="app-shell">
  <header class="app-header">
    <div class="brand"><div class="brand-mark">F</div><div><strong>FORGE<span>SLICER</span></strong><small>LOCAL PRECISION. PURPOSEFUL PRINTS.</small></div></div>
    <div class="workflow"><span class:current={!printer}><b>01</b> Your printer</span><i>›</i><span class:current={!!printer && tab === 'prepare'}><b>02</b> Material & objective</span><i>›</i><span class:current={tab === 'preview'}><b>03</b> Preview & export</span></div>
    <div class="header-actions"><button class="quiet small guide-header" on:click={() => openGuide()}>Profile guide</button><button class="icon-button" title="Toggle light or dark theme" aria-label="Toggle theme" on:click={toggleTheme}>{light ? '☾' : '☀'}</button><button class="quiet small" disabled={busy} on:click={() => openProfiles()}>Profiles</button></div>
  </header>
  <input class="hidden" type="file" accept=".stl,.3mf" bind:this={fileInput} on:change={() => importModel(fileInput.files?.[0])}/>
  <input class="hidden" type="file" accept=".json,application/json" bind:this={printerInput} on:change={() => importPrinter(printerInput.files?.[0])}/>
  {#if !printer}
  <main class="printer-setup-workspace">
    <aside class="setup-navigation"><div class="panel-label">WORKSPACE SETUP</div><div class="setup-step active"><b>01</b><div><strong>Your printer</strong><small>Import verified hardware limits</small></div></div><div class="setup-step"><b>02</b><div><strong>Material recipe</strong><small>Choose compatible process values</small></div></div><div class="setup-step"><b>03</b><div><strong>Print objective</strong><small>Calculate within your limits</small></div></div><div class="setup-local-note"><span class="status-dot"></span><strong>Everything stays local</strong><p>Printer profiles are portable files. No account, cloud service, or in-app AI is required.</p></div><button class="quiet small setup-model-import" disabled title="Configure your printer before adding a model">＋ Add model · STL / 3MF</button></aside>
    <section class="setup-content"><div class="eyebrow">Machine configuration</div><h1>Start with your printer.</h1><p class="setup-intro">Import a portable profile for your exact machine. Forge uses its build volume, nozzle, firmware, temperatures, and configured flow caps to shape the entire slicing workspace.</p>
      {#if initialLoading}<div class="setup-loading"><span class="spinner"></span> Loading your saved printer profiles…</div>{:else if !state}<div class="alert error">Could not load the local workspace. <button class="secondary small" on:click={refresh}>Reconnect</button></div>{:else}
      <div class="setup-primary-actions"><div class="setup-import-card"><div class="setup-card-icon">↥</div><h2>Import your printer profile</h2><p>Already have a compatible <code>.json</code> file? Import it here. Forge validates every required field before activating the machine.</p><button class="primary" disabled={printerImportBusy} on:click={() => printerInput.click()}>{printerImportBusy ? 'Validating printer…' : 'Import printer profile'}<span>→</span></button><small>Portable JSON · versioned schema · no guessed hardware values</small></div><div class="setup-guide-card"><div class="setup-card-icon">▤</div><h2>Read the profile guide</h2><p>Learn what to collect, how to create a profile manually, or how to use the complete documentation with an external assistant.</p><button class="secondary" on:click={() => openGuide()}>Read profile guide →</button><a href="/api/profile-kit" download>Download complete profile kit ↓</a></div></div>
      {#if printerErrors.length}<div class="setup-import-errors alert error" role="alert"><strong>Printer profile was not activated</strong><ul>{#each printerErrors as reason}<li>{reason}</li>{/each}</ul>{#if printerDraftText}<button class="secondary small" on:click={() => openProfiles('printer',printerDraftText,printerErrors)}>Correct imported JSON</button>{/if}<button class="quiet small" on:click={() => openGuide('configuration/validation-rules.md')}>Understand validation rules →</button></div>{/if}
      {#if state.printers.length}<div class="saved-printer-choice"><label class="field-label" for="saved-printer">Or select one of your saved printers</label><select id="saved-printer" bind:value={printerId} on:change={selectPrinter}><option value="" disabled>Select a saved printer</option>{#each state.printers as saved}<option value={saved.id}>{saved.name}</option>{/each}</select></div>{/if}
      <section class="setup-data-section"><h2>What your profile controls</h2><div class="setup-capability-grid"><div><span>01</span><strong>Build plate & placement</strong><p>Actual dimensions, bed shape, coordinate origin, and excluded regions.</p></div><div><span>02</span><strong>Extrusion & materials</strong><p>Nozzle and filament diameter, configured flow caps, and retraction limits.</p></div><div><span>03</span><strong>Motion & firmware</strong><p>Speed, acceleration, supported commands, and startup/shutdown requirements.</p></div><div><span>04</span><strong>Thermal capabilities</strong><p>Nozzle and bed temperature ranges, cooling, and compatible material recipes.</p></div></div></section>
      <div class="setup-manual-row"><div><h3>No profile yet?</h3><p>Create an unfilled draft. The guide explains every field; unknown critical values stay blank until you can verify them.</p></div><button class="secondary" on:click={() => openProfiles('printer')}>Create printer profile</button></div>
      {/if}
    </section>
  </main>
  {:else}
  <section class="active-machine" aria-label="Active printer capabilities"><div class="active-machine-main"><div class="machine-symbol">▤</div><div class="machine-name"><div class="eyebrow">YOUR ACTIVE PRINTER</div><strong>{printer.name}</strong><small>{printer.manufacturer} / {printer.model} · {printer.firmware.family} {printer.firmware.version}</small></div><div class="machine-switch"><label class="field-label" for="active-printer">Switch saved printer</label><select id="active-printer" bind:value={printerId} disabled={busy} on:change={selectPrinter}>{#each state?.printers ?? [] as saved}<option value={saved.id}>{saved.name}</option>{/each}</select></div><div class="machine-actions"><button class="secondary small" disabled={busy || printerImportBusy} on:click={() => printerInput.click()}>Import printer</button><button class="quiet small" disabled={busy} on:click={() => openProfiles('printer')}>Edit profile</button><button class="quiet small" on:click={() => openGuide()}>Guide</button></div></div><div class="machine-metrics"><div><span>BUILD VOLUME</span><strong>{printer.buildVolume.width} × {printer.buildVolume.depth} × {printer.buildVolume.height} <small>mm</small></strong><small>{printer.buildVolume.shape} · {printer.buildVolume.origin} origin</small></div><div><span>NOZZLE / FILAMENT</span><strong>{printer.extruders[0].nozzleDiameter} / {printer.extruders[0].filamentDiameter} <small>mm</small></strong><small>{printer.extruders[0].type} extrusion</small></div><div><span>MOTION LIMITS</span><strong>{printer.motion.maxSpeed} <small>mm/s print</small></strong><small>{printer.motion.maxTravelSpeed} mm/s travel · {printer.motion.maxAcceleration} mm/s²</small></div><div><span>THERMAL LIMITS</span><strong>{printer.thermal.minNozzle}–{printer.thermal.maxNozzle} <small>°C nozzle</small></strong><small>{printer.thermal.hasHeatedBed ? `${printer.thermal.minBed}–${printer.thermal.maxBed} °C bed` : 'No heated bed'} · {printer.thermal.partCooling ? 'part cooling' : 'no part cooling'}</small></div><div><span>CONFIGURED FLOW CAP</span><strong>{printer.extruders[0].maxVolumetricFlow} <small>mm³/s</small></strong><small>{printer.firmware.gcodeFlavor} · {printer.firmware.extrusionMode} extrusion</small></div></div><details class="machine-capabilities"><summary>Declared capabilities & firmware boundaries</summary><div><span class:enabled={printer.capabilities.autoBedLeveling}>Bed leveling: {printer.capabilities.autoBedLeveling ? 'declared' : 'unavailable'}</span><span class:enabled={printer.capabilities.firmwareRetraction}>Firmware retraction: {printer.capabilities.firmwareRetraction ? 'declared' : 'unavailable'}</span><span class:enabled={printer.capabilities.pressureAdvance}>Pressure advance: {printer.capabilities.pressureAdvance ? 'declared' : 'unavailable'}</span><span>{printer.buildVolume.excludedRegions?.length ?? 0} excluded bed regions</span><p>Declared capabilities describe the imported machine. The supported slicing adapter may apply a narrower feature set. Limits and unsupported commands are checked before export.</p></div></details></section>
  <main class="workspace">
    <aside class="model-sidebar">
      <div class="panel-label">PROJECT <span>01 PLATE</span></div>
      <button class="import-button" disabled={busy || importing} on:click={() => fileInput.click()}><span>＋</span>{importing ? 'Importing model…' : 'Import model'}<small>STL / 3MF</small></button>
      <div class="section-heading">Objects <span>{model ? '1' : '0'}</span></div>
      {#if model}
        <div class="object-card"><div class="object-icon">◇</div><div><strong title={model.name}>{model.name}</strong><small>{number(model.triangles, 0)} triangles</small></div><span class="object-dot"></span></div>
        <div class="object-data"><div><span>Envelope</span><strong>{(exactDimensions.length ? exactDimensions : dimensions).map(v => number(v)).join(' × ')} <small>mm</small></strong></div><div><span>Mesh volume</span><strong>{number(model.volumeMm3 * transform.scale.reduce((a, b) => a * b, 1) / 1000, 2)} <small>cm³</small></strong></div></div>
        <div class="section-heading transform-heading">Transform <button class="quiet small" disabled={busy} on:click={resetTransform}>Reset</button></div>
        <div class="segmented"><button class:active={activeTool === 'move'} on:click={() => activeTool = 'move'}>Move</button><button class:active={activeTool === 'rotate'} on:click={() => activeTool = 'rotate'}>Rotate</button><button class:active={activeTool === 'scale'} on:click={() => activeTool = 'scale'}>Scale</button></div>
        <div class="transform-fields">{#each ['X', 'Y', 'Z'] as axis, i}<label><span class="axis axis-{axis.toLowerCase()}">{axis}</span><input disabled={busy} aria-label={`${activeTool} ${axis}`} type="number" min={activeTool === 'scale' ? .01 : undefined} step={activeTool === 'scale' ? 1 : .5} value={activeTool === 'move' ? transform.position[i] : activeTool === 'rotate' ? transform.rotation[i] : transform.scale[i] * 100} on:change={e => changeTransform(activeTool === 'move' ? 'position' : activeTool === 'rotate' ? 'rotation' : 'scale', i, e)}/><small>{activeTool === 'move' ? 'mm' : activeTool === 'rotate' ? '°' : '%'}</small></label>{/each}</div>
        {#if activeTool === 'scale'}<label class="check-line"><input type="checkbox" bind:checked={uniformScale} disabled={busy}/> Uniform scaling</label>{/if}
        <div class="object-actions"><button class="secondary small" disabled={busy} on:click={center}>⌖ Center on bed</button><button class="secondary small" disabled={busy} on:click={() => viewport.orient()}>◇ Auto-orient</button></div>
        <p class="hint">Auto-orient compares face-based candidates using a geometric support proxy. Inspect the result.</p>
        {#if model.warnings?.length}<div class="mesh-warnings">{#each model.warnings as warning}<p>△ {warning}</p>{/each}</div>{/if}
      {:else}<div class="empty-object compact-empty"><p>No model on this plate</p><small>Use the small import control above when your machine and material are ready.</small></div>{/if}
      <div class="sidebar-bottom"><span class="status-dot" class:warning={!state?.engine.available}></span><div><strong>{state?.engine.available ? 'PrusaSlicer connected' : 'Connect slicing engine'}</strong><button class="quiet small" disabled={busy} on:click={() => engineOpen = true}>{state?.engine.available ? 'Engine settings' : 'Set executable path →'}</button></div></div>
    </aside>

    <section class="plate-workspace" aria-label="Build plate and toolpath preview">
      <Viewport bind:this={viewport} {model} {vertices} {printer} {transform} {preview} previewMode={tab === 'preview'} {layer} {singleLayer} {travel} {printOrder} {light} onorient={(rotation, note) => {invalidate(); transform = {...transform, rotation}; notice = note;}} onerror={value => error = value} riskTriangles={readiness?.riskTriangles??[]} {showRisks}/>
      <div class="viewport-top"><div class="view-tabs"><button class:active={tab === 'prepare'} on:click={() => tab = 'prepare'}>Prepare</button><button class:active={tab === 'preview'} disabled={!preview} on:click={() => tab = 'preview'}>Toolpaths {#if preview}<span>{preview.layers.length}</span>{/if}</button></div><div class="view-controls"><button title="Top view" on:click={() => viewport.view('top')}>Top</button><button title="Front view" on:click={() => viewport.view('front')}>Front</button><button title="Isometric view" on:click={() => viewport.view('iso')}>Iso</button><button title="Fit to view" aria-label="Fit build plate" on:click={() => viewport.fit()}>⛶</button></div></div>
      {#if !model && !initialLoading}<div class="plate-ready-note"><span class="status-dot"></span><div><strong>{printer.name} build plate</strong><small>Ready for a model after selecting a compatible material recipe.</small></div></div>{/if}
      {#if initialLoading}<div class="plate-empty"><span class="spinner large"></span><p>Loading local workspace…</p></div>{/if}
      <div class="plate-caption"><span>XY BUILD PLATE</span><strong>{printer ? `${printer.buildVolume.width} × ${printer.buildVolume.depth} × ${printer.buildVolume.height} mm` : 'Select printer'}</strong></div>
      {#if tab === 'prepare'}<div class="viewport-help">Drag to orbit <span>·</span> Right-drag to pan <span>·</span> Scroll to zoom</div>{/if}
      {#if tab === 'preview' && preview}
        <div class="preview-legend"><span><i style="background:#44d8bd"></i>Perimeters</span><span><i style="background:#6996f1"></i>Infill</span><span><i style="background:#e9b65f"></i>Supports</span><span><i style="background:#bb8fe8"></i>Other extrusion</span><label><input type="checkbox" bind:checked={travel}/>Travel</label></div>
        <div class="layer-panel"><div class="layer-heading"><strong>Layer {layer + 1}<span> / {preview.layers.length}</span></strong><span>Z {number(currentLayerZ, 3)} mm</span><label class="check-line"><input type="checkbox" bind:checked={singleLayer}/> Single layer</label></div><div class="layer-slider"><button class="icon-button" disabled={layer <= 0} on:click={() => layer--}>−</button><input type="range" min="0" max={Math.max(0, preview.layers.length - 1)} step="1" bind:value={layer} aria-label="Preview layer"/><button class="icon-button" disabled={layer >= preview.layers.length - 1} on:click={() => layer++}>＋</button></div><div class="order-control"><span>Print order</span><input type="range" min="0" max="100" step=".1" bind:value={printOrder} aria-label="Print order percentage"/><span>{Math.round(printOrder)}%</span></div></div>
      {/if}
      {#if busy}<div class="job-overlay"><div><span class="spinner"></span><strong>{job?.status === 'optimizing' ? 'Searching feasible strategies' : job?.status === 'validating' ? 'Validating printer instructions' : 'Generating toolpaths'}</strong><span>{Math.round(progress)}%</span></div><progress value={progress} max="100"></progress><p>{job?.message}</p><button class="quiet small" on:click={cancel}>Cancel job</button></div>{/if}
    </section>

    <aside class="settings-sidebar">
      <div class="panel-label">PRINT SETUP <span>LOCAL ENGINE</span></div>
      {#if model}<ReadinessPanel {model} {printer} {transform} {supportAngle} {supportMode} disabled={busy} onreport={value=>readiness=value} onaction={readinessAction} onguide={()=>openGuide('configuration/supports.md')} bind:showRisks/>{/if}
      <section class="settings-section material-section"><div class="section-number">01</div><h2>Material recipe</h2><label class="field-label" for="filament">Recipes for {printer.model}</label><select id="filament" disabled={busy || materialsLoading} bind:value={filamentId} on:change={invalidate}><option value="" disabled>{materialsLoading ? 'Checking printer limits…' : 'Select a compatible recipe'}</option>{#each materials as material}<option value={material.profile.id} disabled={!material.compatible}>{material.profile.name}{material.compatible ? '' : ' — unavailable'}</option>{/each}</select>{#if materialsError}<div class="material-status incompatible">{materialsError}<button class="quiet small" on:click={() => loadMaterials(printer.id)}>Retry compatibility check</button></div>{:else if filament && materialStatus}<div class="profile-meta"><span>{filament.nozzleTemperature} °C nozzle</span><span>{filament.bedTemperature} °C bed</span></div><div class="material-status" class:incompatible={!materialStatus.compatible}><span class="status-dot" class:warning={!materialStatus.compatible}></span>{materialStatus.compatible ? 'Fits declared machine limits' : materialStatus.reasons.join(' ')}</div><p class="hint">Effective flow ceiling: {number(Math.min(printer.extruders[0].maxVolumetricFlow,filament.maxVolumetricFlow))} mm³/s. Layer range: {number(Math.max(filament.minLayerHeight,printer.extruders[0].nozzleDiameter*.2),3)}–{number(Math.min(filament.maxLayerHeight,printer.extruders[0].nozzleDiameter*.8),3)} mm.</p>{/if}{#if materialStatus?.notes?.length || filament?.notes?.length}<div class="material-notes">{#each [...new Set([...(materialStatus?.notes??[]),...(filament?.notes??[])])] as note}<p>{note}</p>{/each}</div>{/if}<details class="material-catalogue"><summary>View all {materials.length} starter recipes</summary>{#each materials as material}<div class:unavailable={!material.compatible}><strong>{material.profile.name}<small>{material.compatible ? 'Within declared limits' : 'Unavailable for this printer'}</small></strong><span>{material.profile.nozzleTemperature} °C nozzle / {material.profile.bedTemperature} °C bed</span>{#each material.reasons as reason}<p>{reason}</p>{/each}{#each material.notes??material.profile.notes??[] as note}<p class="material-note">{note}</p>{/each}</div>{/each}</details><p class="material-caveat">Starter recipes check declared temperature, cooling, and layer limits. Enclosure needs, bed adhesion, nozzle wear, and real material behavior still require your verification.</p><div class="material-links"><button class="quiet profile-link" disabled={busy} on:click={() => openProfiles('filament')}>Manage / import material</button><button class="quiet profile-link" on:click={() => openGuide('configuration/material-catalogue.md')}>Material guide</button></div></section>
      <section class="settings-section"><div class="section-number">02</div><h2>Choose your objective</h2><div class="mode-grid">{#each modes as option}<button class="mode-card" class:active={mode === option.id} disabled={busy} title={option.description} on:click={() => {mode = option.id; invalidate();}}><span class="mode-icon">{option.icon}</span><span>{option.name}</span>{#if mode === option.id}<i>✓</i>{/if}</button>{/each}</div><p class="mode-description">{selectedMode.description}</p></section>
      <SupportSettings bind:mode={supportMode} bind:style={supportStyle} bind:placement={supportPlacement} bind:angle={supportAngle} disabled={busy} onchange={invalidate} onguide={()=>openGuide('configuration/supports.md')} onsave={savePreferences}/>
      <details class="advanced-settings"><summary>Advanced constraints <span>＋</span></summary><div class="advanced-body"><label class="field-label" for="budget">Candidate budget <span>{budget}</span></label><input id="budget" type="range" min="16" max="256" step="16" bind:value={budget} disabled={busy} on:change={invalidate}/><div class="field-pair"><label>Minimum walls<input type="number" min="1" max="12" step="1" bind:value={minWalls} disabled={busy} on:change={invalidate}/></label><label>Minimum infill %<input type="number" min="0" max="100" step="1" bind:value={minInfill} disabled={busy} on:change={invalidate}/></label></div>{#if mode === 'strength'}<label class="check-line"><input type="checkbox" bind:checked={useLoadDirection} disabled={busy} on:change={invalidate}/> Specify assumed load direction</label>{#if useLoadDirection}<div class="load-fields">{#each ['X', 'Y', 'Z'] as axis, i}<label>{axis}<input type="number" step=".1" bind:value={loadDirection[i]} disabled={busy} on:change={invalidate}/></label>{/each}</div>{/if}<p class="hint">A direction describes the assumed loading axis. Strength estimates are engineering proxies and require physical validation.</p>{/if}<p class="hint">Hardware, thermal, volumetric-flow, and build-volume limits always apply.</p></div></details>
      <div class="slice-area">
        {#if preview && job?.status === 'complete'}<div class="result-summary"><div><span>Estimated print time</span><strong>{duration(preview.estimatedSeconds)}</strong></div><div><span>Filament</span><strong>{number(preview.massG)} <small>g</small></strong><small>{number(preview.filamentMm / 1000, 2)} m</small></div><button class="quiet report-button" on:click={() => reportOpen = true}>View optimization report ↗</button></div><button class="primary full export-button" on:click={downloadGcode}>↓ Export G-code</button><button class="quiet full small" disabled={busy} on:click={slice}>Recalculate & slice</button>
        {:else}<div class="slice-readiness"><span class="status-dot" class:warning={!model || !materialCompatible || !placementFits || !state?.engine.available}></span>{materialsLoading ? 'Checking material compatibility' : !materialCompatible ? 'Select a compatible material recipe' : !model ? 'Machine ready · add a model when ready' : placementBusy ? 'Checking placement against machine bounds' : !placementFits ? 'Model does not fit this machine' : !state?.engine.available ? 'Native engine required' : `Ready for ${printer.name}`}</div>{#if placementReasons.length}<div class="placement-reasons">{#each placementReasons as reason}<p>{reason}</p>{/each}</div>{/if}<button class="primary full slice-button" disabled={!model || !printer || !filament || !materialCompatible || !placementFits || placementBusy || busy || submitting || importing || !state?.engine.available} on:click={slice}>{busy ? 'Processing…' : submitting ? 'Starting…' : 'Optimize & slice'}<span>→</span></button>{/if}
        <p class="slice-footnote">Deterministic calculations. No cloud. No AI.</p>
      </div>
    </aside>
  </main>
  {/if}
  <footer class="status-bar"><span><i class="status-dot"></i>{busy ? 'Working locally' : 'Local workspace'}</span><span>{model ? `${model.name} · ${number(model.triangles, 0)} triangles` : 'No model loaded'}</span><span>FORGE {state?.version ?? '0.1.0'}</span></footer>
</div>

{#if error}<div class="toast error" role="alert"><span>△</span><div><strong>Action needs attention</strong><p>{error}</p></div><button class="icon-button" aria-label="Dismiss error" on:click={() => error = ''}>✕</button></div>{:else if notice}<div class="toast" role="status"><span>✓</span><p>{notice}</p><button class="icon-button" aria-label="Dismiss notification" on:click={() => notice = ''}>✕</button></div>{/if}
{#if dragActive}<div class="drop-overlay"><div><span>＋</span><h2>{printer ? 'Drop a printer profile or model' : 'Drop your printer profile'}</h2><p>{printer ? 'Printer JSON or STL / 3MF' : 'Portable printer configuration .json'} · Validated locally</p></div></div>{/if}
{#if profileOpen}<ProfileManager {printer} {filament} {currentPreferences} initialKind={profileKind} initialText={profileInitialText} initialErrors={profileInitialErrors} onclose={() => profileOpen = false} onsaved={profileSaved} onguide={openGuide}/>{/if}
{#if guideOpen}<Documentation path={guidePath} onclose={() => guideOpen = false} oncreate={() => {guideOpen=false;openProfiles('printer');}}/>{/if}
{#if engineOpen}<div class="modal-backdrop" role="presentation"><div class="modal engine-modal" role="dialog" aria-modal="true" aria-labelledby="engine-title" tabindex="-1"><header class="modal-header"><div><div class="eyebrow">Isolated native slicing</div><h2 id="engine-title">Connect PrusaSlicer</h2></div><button class="icon-button" aria-label="Close engine settings" on:click={() => engineOpen = false}>✕</button></header><p class="muted">Select a locally installed PrusaSlicer executable. Forge uses its native geometry, perimeter, infill, and support algorithms. The engine runs as a cancellable subprocess.</p><label class="field-label" for="engine-path">Executable path</label><input id="engine-path" class="mono full" bind:value={enginePath} placeholder="C:\Program Files\Prusa3D\PrusaSlicer\prusa-slicer-console.exe"/><p class="hint">Windows: prusa-slicer-console.exe · macOS: PrusaSlicer.app/Contents/MacOS/PrusaSlicer · Linux: prusa-slicer</p>{#if state?.engine.available}<div class="alert success">Connected · {state.engine.version || 'PrusaSlicer'}</div>{/if}<div class="about-links"><button class="quiet small" on:click={() => openGuide()}>Offline profile guide</button><a href="/LICENSE" target="_blank" rel="noreferrer">License</a><a href="/THIRD_PARTY_NOTICES.md" target="_blank" rel="noreferrer">Third-party notices</a></div><footer class="modal-footer"><span class="muted">No scripts or shell commands.</span><button class="primary" disabled={engineSaving || !enginePath.trim()} on:click={saveEngine}>{engineSaving ? 'Connecting…' : 'Connect engine'}</button></footer></div></div>{/if}
{#if reportOpen && report}<div class="modal-backdrop" role="presentation"><div class="modal report-modal" role="dialog" aria-modal="true" aria-labelledby="report-title" tabindex="-1"><header class="modal-header"><div><div class="eyebrow">Calculated strategy · {report.evaluated} candidates</div><h2 id="report-title">{selectedMode.name} optimization</h2></div><button class="icon-button" aria-label="Close optimization report" on:click={() => reportOpen = false}>✕</button></header><p class="muted">A bounded search selected this feasible strategy. The result is not a proven global optimum. Native comparisons use both generated toolpaths; analytical search estimates are shown separately.</p><div class="report-metrics"><div><span>Toolpath time estimate</span><strong>{duration(preview?.estimatedSeconds ?? 0)}</strong><small>Calculated from generated G-code</small></div><div><span>Toolpath material</span><strong>{number(preview?.massG ?? 0)} g</strong><small>Extrusion × filament density</small></div></div><SupportComparison {report} onguide={()=>openGuide('configuration/supports.md')}/>{#if report.actual && report.baselineActual}<h3>Native slicing comparison</h3><table><thead><tr><th>Calculated metric</th><th>Baseline</th><th>Selected</th></tr></thead><tbody><tr><td>Print time estimate</td><td>{duration(report.baselineActual.seconds)}</td><td>{duration(report.actual.seconds)}</td></tr><tr><td>Extruded material</td><td>{number(report.baselineActual.massG)} g</td><td>{number(report.actual.massG)} g</td></tr><tr><td>Support filament</td><td>{number(report.baselineActual.supportFilamentMm / 1000, 2)} m</td><td>{number(report.actual.supportFilamentMm / 1000, 2)} m</td></tr><tr><td>Toolpath length</td><td>{number(report.baselineActual.pathMm / 1000, 2)} m</td><td>{number(report.actual.pathMm / 1000, 2)} m</td></tr><tr><td>Slicing computation</td><td>{number(report.baselineActual.sliceSeconds, 2)} s</td><td>{number(report.actual.sliceSeconds, 2)} s</td></tr></tbody></table><div class="comparison-deltas"><span>Time: {changeLabel(report.timeDifferencePercent)}</span><span>Material: {changeLabel(report.massDifferencePercent)}</span></div><p class="hint">Both strategies were sliced from the same transformed geometry. Time is a motion-model estimate; material is calculated from generated extrusion. Differences describe this model, printer, and filament only.</p>{/if}<h3>Analytical search model</h3><table><thead><tr><th>Metric</th><th>Baseline</th><th>Selected</th></tr></thead><tbody><tr><td>Estimated time</td><td>{duration(report.baselinePredicted.seconds)}</td><td>{duration(report.predicted.seconds)}</td></tr><tr><td>Estimated mass</td><td>{number(report.baselinePredicted.massG)} g</td><td>{number(report.predicted.massG)} g</td></tr><tr><td>Layer height</td><td>{number(report.baseline.layerHeight, 3)} mm</td><td>{number(report.selected.layerHeight, 3)} mm</td></tr><tr><td>Walls / infill</td><td>{report.baseline.walls} / {number(report.baseline.infill * 100)}%</td><td>{report.selected.walls} / {number(report.selected.infill * 100)}%</td></tr><tr><td>Print speed</td><td>{number(report.baseline.speed)} mm/s</td><td>{number(report.selected.speed)} mm/s</td></tr></tbody></table><p class="hint">Analytical estimates differ from native toolpath estimates. Neither predicts physical strength or surface finish without calibration. Pareto frontier: {report.paretoCount} candidates.</p>{#if report.changes?.length}<h3>Selected changes</h3><ul>{#each report.changes as item}<li>{item}</li>{/each}</ul>{/if}{#if report.constraints?.length}<h3>Active constraints</h3><ul>{#each report.constraints as item}<li>{item}</li>{/each}</ul>{/if}{#if report.warnings?.length}<h3>Optimizer warnings</h3><ul>{#each report.warnings as item}<li>{item}</li>{/each}</ul>{/if}{#if report.assumptions?.length}<h3>Assumptions & trade-offs</h3><ul>{#each report.assumptions as item}<li>{item}</li>{/each}</ul>{/if}{#if preview?.warnings?.length}<h3>G-code validation notes</h3><ul>{#each preview.warnings as item}<li>{item}</li>{/each}</ul>{/if}<footer class="modal-footer"><span class="muted">Static validation cannot guarantee a physically safe print.</span><button class="primary" on:click={() => reportOpen = false}>Done</button></footer></div></div>{/if}
